<template>
    <div>
        <Head title="Dashboard" />

        <Card
            title="Global Sales by Top Locations"
            icon="language"
            card-header-class="card-header-success"
        >
            <div class="row">
                <div class="md:col-6">
                    <div class="table-responsive table-sales">
                        <table class="table">
                            <thead class="visually-hidden">
                                <tr>
                                    <th scope="col">Flag</th>
                                    <th scope="col">Country</th>
                                    <th scope="col">Sales</th>
                                    <th scope="col">Share</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr v-for="location in salesLocations" :key="location.country">
                                    <td><div class="flag"><img :src="location.flag" alt="" /></div></td>
                                    <td>{{ location.country }}</td>
                                    <td class="text-end">{{ location.sales }}</td>
                                    <td class="text-end">{{ location.share }}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>
                <div class="md:col-6">
                    <WorldSalesMap :values="salesByCountry" />
                </div>
            </div>
        </Card>

        <div class="row">
            <div v-for="chart in charts" :key="chart.id" class="md:col-4">
                <ChartCard
                    :title="chart.title"
                    :color="chart.color"
                    :description="chart.description"
                    :updated-text="chart.updatedText"
                >
                    <template #chart>
                        <div class="dashboard-chart">
                            <Chart
                                :canva-id="chart.id"
                                :type="chart.type"
                                :data="chart.data"
                                :options="chart.options"
                                role="img"
                                :aria-label="`${chart.title} chart`"
                            />
                        </div>
                    </template>

                    <template v-if="chart.id === 'daily-sales'" #description>
                        <span class="text-success"><i class="material-icons" aria-hidden="true">arrow_upward</i> 55%</span>
                        increase in today sales.
                    </template>
                </ChartCard>
            </div>
        </div>

        <div class="row">
            <div v-for="metric in metrics" :key="metric.label" class="lg:col-3 md:col-6 sm:col-6">
                <Card class="card-stats" :icon="metric.icon" :card-header-class="`card-header-${metric.color}`">
                    <template #header>
                        <p class="card-category">{{ metric.label }}</p>
                        <h3 class="card-title">{{ metric.value }}</h3>
                    </template>

                    <template #footer>
                        <div class="stats">
                            <i class="material-icons" :class="metric.footerIconClass" aria-hidden="true">{{ metric.footerIcon }}</i>
                            <a v-if="metric.href" :href="metric.href">{{ metric.footer }}</a>
                            <template v-else>{{ metric.footer }}</template>
                        </div>
                    </template>
                </Card>
            </div>
        </div>

        <section aria-labelledby="manage-listings">
            <h3 id="manage-listings" class="mb-4">Manage Listings</h3>
            <div class="row">
                <div v-for="listing in listings" :key="listing.title" class="md:col-4">
                    <Card class="card-product" card-header-class="card-header-image">
                        <template #header>
                            <img class="img" :src="listing.image" alt="" />
                        </template>

                        <h4 class="card-title">{{ listing.title }}</h4>
                        <div class="card-description">{{ listing.description }}</div>

                        <template #footer>
                            <div class="price">
                                <h4>{{ listing.price }}</h4>
                            </div>
                            <div class="stats">
                                <p class="card-category">
                                    <i class="material-icons" aria-hidden="true">place</i>
                                    {{ listing.location }}
                                </p>
                            </div>
                        </template>
                    </Card>
                </div>
            </div>
        </section>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import Chart from '@scaffold/components/Chart.vue';
import ChartCard from '@scaffold/components/ChartCard.vue';
import WorldSalesMap from '@scaffold/components/WorldSalesMap.vue';
import australiaFlag from '@scaffold-assets/flags/AU.png';
import brazilFlag from '@scaffold-assets/flags/BR.png';
import germanyFlag from '@scaffold-assets/flags/DE.png';
import unitedKingdomFlag from '@scaffold-assets/flags/GB.png';
import romaniaFlag from '@scaffold-assets/flags/RO.png';
import unitedStatesFlag from '@scaffold-assets/flags/US.png';
import barcelonaImage from '@scaffold-assets/listing-barcelona.jpg';
import londonImage from '@scaffold-assets/listing-london.jpg';
import milanImage from '@scaffold-assets/listing-milan.jpg';

function chartOptions(type, max, stepSize) {
    const tickColor = 'rgba(255, 255, 255, .85)';
    const gridColor = 'rgba(255, 255, 255, .2)';

    return {
        maintainAspectRatio: false,
        plugins: { legend: { display: false } },
        scales: {
            x: {
                border: { display: false, dash: [2, 2] },
                grid: { color: gridColor, display: type !== 'bar', drawTicks: false },
                ticks: { color: tickColor, maxRotation: 0, padding: 6 },
            },
            y: {
                min: 0,
                max,
                border: { display: false, dash: [2, 2] },
                grid: { color: gridColor, drawTicks: false },
                ticks: { color: tickColor, padding: 6, stepSize },
            },
        },
    };
}

export default {
    name: 'Dashboard',
    layout: { pageTitle: 'Dashboard' },
    components: { Card, Chart, ChartCard, Head, WorldSalesMap },
    data() {
        return {
            salesLocations: [
                { country: 'USA', sales: '2.920', share: '53.23%', flag: unitedStatesFlag },
                { country: 'Germany', sales: '1.300', share: '20.43%', flag: germanyFlag },
                { country: 'Australia', sales: '760', share: '10.35%', flag: australiaFlag },
                { country: 'United Kingdom', sales: '690', share: '7.87%', flag: unitedKingdomFlag },
                { country: 'Romania', sales: '600', share: '5.94%', flag: romaniaFlag },
                { country: 'Brasil', sales: '550', share: '4.34%', flag: brazilFlag },
            ],
            salesByCountry: {
                AU: 760, BR: 550, CA: 120, DE: 1300, FR: 540, GB: 690,
                GE: 200, IN: 200, RO: 600, RU: 300, US: 2920,
            },
            listings: [
                {
                    title: 'Cozy 5 Stars Apartment',
                    description: 'The place is close to Barceloneta Beach and bus stop just 2 min by walk and near to "Naviglio" where you can enjoy the main night life in Barcelona.',
                    image: barcelonaImage,
                    price: '$899/night',
                    location: 'Barcelona, Spain',
                },
                {
                    title: 'Office Studio',
                    description: 'The place is close to Metro Station and bus stop just 2 min by walk and near to "Naviglio" where you can enjoy the night life in London, UK.',
                    image: londonImage,
                    price: '$1.119/night',
                    location: 'London, UK',
                },
                {
                    title: 'Beautiful Castle',
                    description: 'The place is close to Metro Station and bus stop just 2 min by walk and near to "Naviglio" where you can enjoy the main night life in Milan.',
                    image: milanImage,
                    price: '$459/night',
                    location: 'Milan, Italy',
                },
            ],
            charts: [
                {
                    id: 'website-views',
                    title: 'Website Views',
                    color: 'rose',
                    type: 'bar',
                    description: 'Last Campaign Performance',
                    updatedText: 'campaign sent 2 days ago',
                    labels: ['J', 'F', 'M', 'A', 'M', 'J', 'J', 'A', 'S', 'O', 'N', 'D'],
                    values: [542, 443, 320, 780, 553, 453, 326, 434, 568, 610, 756, 895],
                    max: 1000,
                    step: 200,
                },
                {
                    id: 'daily-sales',
                    title: 'Daily Sales',
                    color: 'success',
                    type: 'line',
                    updatedText: 'updated 4 minutes ago',
                    labels: ['M', 'T', 'W', 'T', 'F', 'S', 'S'],
                    values: [12, 17, 7, 17, 23, 18, 38],
                    max: 50,
                    step: 10,
                },
                {
                    id: 'completed-tasks',
                    title: 'Completed Tasks',
                    color: 'info',
                    type: 'line',
                    description: 'Last Campaign Performance',
                    updatedText: 'campaign sent 2 days ago',
                    labels: ['12p', '3p', '6p', '9p', '12p', '3a', '6a', '9a'],
                    values: [230, 750, 450, 300, 280, 240, 200, 190],
                    max: 1000,
                    step: 200,
                },
            ].map(({ labels, values, max, step, ...chart }) => {
                const color = 'rgba(255, 255, 255, .8)';

                return {
                    ...chart,
                    data: {
                        labels,
                        datasets: [{
                            label: chart.title,
                            data: values,
                            backgroundColor: color,
                            borderColor: color,
                            borderWidth: chart.type === 'line' ? 4 : 0,
                            pointRadius: 4,
                            maxBarThickness: 10,
                        }],
                    },
                    options: chartOptions(chart.type, max, step),
                };
            }),
            metrics: [
                {
                    label: 'Bookings',
                    value: '184',
                    color: 'warning',
                    icon: 'weekend',
                    footerIcon: 'warning',
                    footerIconClass: 'text-danger',
                    footer: 'Get More Space...',
                    href: '#pablo',
                },
                {
                    label: 'Website Visits',
                    value: '75.521',
                    color: 'rose',
                    icon: 'equalizer',
                    footerIcon: 'local_offer',
                    footer: 'Tracked from Google Analytics',
                },
                {
                    label: 'Revenue',
                    value: '$34,245',
                    color: 'success',
                    icon: 'store',
                    footerIcon: 'date_range',
                    footer: 'Last 24 Hours',
                },
                {
                    label: 'Followers',
                    value: '+245',
                    color: 'info',
                    icon: 'group',
                    footerIcon: 'update',
                    footer: 'Just Updated',
                },
            ],
        };
    },
};
</script>

<style scoped>
.dashboard-chart {
    position: relative;
    height: 10rem;
}

</style>
