<template>
    <div ref="viewport" class="world-sales-map" @pointerleave="hoveredRegion = ''">
        <svg
            :viewBox="viewBox"
            role="img"
            aria-label="World map showing sales by country"
            :class="{ 'is-zoomed': zoom > 1 }"
            @pointerdown="startPan"
            @pointermove="handlePointerMove"
            @pointerup="stopPan"
            @pointercancel="stopPan"
            @lostpointercapture="stopPan"
        >
            <g class="world-sales-map-regions" :class="{ 'is-panning': panStart }" :style="{ transform: mapTransform }">
                <path
                    v-for="(region, code) in regions"
                    :key="code"
                    :d="region.path"
                    :style="{ fill: regionFill(code) }"
                    @pointerenter="hoveredRegion = panStart ? '' : region.name"
                    @pointerleave="hoveredRegion = ''"
                />
            </g>
        </svg>

        <div class="world-sales-map-controls d-flex flex-column gap-1">
            <button type="button" aria-label="Zoom in" @click="setZoom(zoom * 1.6)">+</button>
            <button type="button" aria-label="Zoom out" @click="setZoom(zoom / 1.6)">−</button>
        </div>

        <div v-if="hoveredRegion" class="world-sales-map-tip" :style="tipStyle">{{ hoveredRegion }}</div>
    </div>
</template>

<script>
// Geometry, color normalization and centered zoom follow the template's jVectorMap.
import worldMap from '@scaffold-assets/world-mill.json';

export default {
    name: 'WorldSalesMap',
    props: {
        values: { type: Object, required: true },
    },
    data() {
        return {
            zoom: 1,
            pan: { x: 0, y: 0 },
            panStart: null,
            hoveredRegion: '',
            pointer: { x: 0, y: 0, leftHalf: true },
        };
    },
    computed: {
        regions() {
            return worldMap.paths;
        },
        viewBox() {
            return `0 0 ${worldMap.width} ${worldMap.height}`;
        },
        mapTransform() {
            return `translate(${this.pan.x}px, ${this.pan.y}px) scale(${this.zoom})`;
        },
        tipStyle() {
            const { x, y, leftHalf } = this.pointer;

            return {
                left: `${x}px`,
                top: `${y}px`,
                transform: leftHalf ? 'translate(12px, -50%)' : 'translate(calc(-100% - 12px), -50%)',
            };
        },
        valueRange() {
            const values = Object.values(this.values).map((value) => value ** 0.2);
            return [Math.min(...values), Math.max(...values)];
        },
    },
    methods: {
        regionFill(code) {
            const value = this.values[code];
            if (value === undefined) {
                return 'light-dark(#e4e4e4, #454545)';
            }

            const [min, max] = this.valueRange;
            const share = max === min ? 1 : (value ** 0.2 - min) / (max - min);
            const light = Math.round(170 - share * 102);
            const dark = Math.round(170 + share * 58);
            return `light-dark(rgb(${light} ${light} ${light}), rgb(${dark} ${dark} ${dark}))`;
        },
        setZoom(requestedZoom) {
            const zoom = Math.min(8, Math.max(1, requestedZoom));
            const scale = zoom / this.zoom;
            this.zoom = zoom;
            this.hoveredRegion = '';
            this.updatePan(this.pan.x * scale, this.pan.y * scale);
        },
        updatePan(x, y) {
            const { width, height } = this.$refs.viewport.getBoundingClientRect();
            const fit = Math.min(width / worldMap.width, height / worldMap.height);
            if (!fit) {
                return;
            }

            const maxX = Math.max(0, (worldMap.width * this.zoom - width / fit) / 2);
            const maxY = Math.max(0, (worldMap.height * this.zoom - height / fit) / 2);
            this.pan = {
                x: Math.max(-maxX, Math.min(maxX, x)),
                y: Math.max(-maxY, Math.min(maxY, y)),
            };
        },
        startPan(event) {
            if (this.zoom === 1 || !event.isPrimary || event.button !== 0) {
                return;
            }

            this.hoveredRegion = '';
            this.panStart = {
                x: event.clientX,
                y: event.clientY,
                panX: this.pan.x,
                panY: this.pan.y,
            };
            event.currentTarget.setPointerCapture(event.pointerId);
        },
        handlePointerMove(event) {
            const bounds = this.$refs.viewport.getBoundingClientRect();
            const x = event.clientX - bounds.left;
            const y = event.clientY - bounds.top;
            this.pointer = { x, y, leftHalf: x < bounds.width / 2 };

            if (this.panStart && event.isPrimary) {
                const fit = Math.min(bounds.width / worldMap.width, bounds.height / worldMap.height);
                this.updatePan(
                    this.panStart.panX + (event.clientX - this.panStart.x) / fit,
                    this.panStart.panY + (event.clientY - this.panStart.y) / fit,
                );
            }
        },
        stopPan(event) {
            if (event.isPrimary) {
                this.panStart = null;
            }
        },
    },
};
</script>

<style scoped>
.world-sales-map {
    position: relative;
    block-size: 300px;
}

.world-sales-map svg {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    overflow: hidden;
    touch-action: auto;
    user-select: none;
}

.world-sales-map svg.is-zoomed {
    cursor: grab;
    touch-action: none;
}

.world-sales-map svg:has(.is-panning) {
    cursor: grabbing;
}

.world-sales-map-regions {
    transform-origin: center;
    transition: transform 230ms linear;
}

.world-sales-map-regions.is-panning {
    transition: none;
}

.world-sales-map-regions path {
    fill-opacity: .9;
}

.world-sales-map-regions path:hover {
    fill-opacity: .8;
}

.world-sales-map-controls {
    position: absolute;
    inset-block-start: 10px;
    inset-inline-start: 10px;
}

.world-sales-map-controls button {
    inline-size: 16px;
    block-size: 16px;
    padding: 0;
    border: 0;
    border-radius: 3px;
    background: #292929;
    color: white;
    font-size: 12px;
    line-height: 1;
}

.world-sales-map-tip {
    position: absolute;
    z-index: 4;
    pointer-events: none;
    padding: 5px 10px;
    border-radius: 4px;
    background: var(--bg-body);
    color: var(--fg-body);
    box-shadow: 0 2px 8px rgb(0 0 0 / 20%);
    font-size: 12px;
    white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
    .world-sales-map-regions {
        transition: none;
    }
}
</style>
